package com.tanidikvar.api.verification.service;import com.tanidikvar.api.auth.service.*;import org.slf4j.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;import org.springframework.stereotype.Component;import org.springframework.transaction.event.TransactionalEventListener;
@Component public class EducationVerificationMailSender{private static final Logger log=LoggerFactory.getLogger(EducationVerificationMailSender.class);private final AuthMailDelivery delivery;private final ThreadPoolTaskExecutor executor;private final String from;public EducationVerificationMailSender(AuthMailDelivery delivery,ThreadPoolTaskExecutor authMailExecutor,@Value("${app.mail.from}")String from){this.delivery=delivery;this.executor=authMailExecutor;this.from=from;}@TransactionalEventListener public void send(EducationVerificationMailEvent event){try{executor.execute(()->deliver(event));}catch(RuntimeException exception){log.warn("education_verification_mail_queue_failed type={}",exception.getClass().getSimpleName());}}private void deliver(EducationVerificationMailEvent event){String text="TanıdıkVar okul e-postası doğrulama kodun: "+event.code()+"\nKod 15 dakika geçerlidir.";try{delivery.send(new AuthMailMessage(from,event.email(),"TanıdıkVar — Okul e-postanı doğrula",text,"<p>Okul e-postası doğrulama kodun:</p><p style=\"font-size:28px;font-weight:bold\">"+event.code()+"</p><p>Kod 15 dakika geçerlidir.</p>"));}catch(RuntimeException exception){log.warn("education_verification_mail_failed type={}",exception.getClass().getSimpleName());}}}
